import { Link, useLocation } from "react-router-dom";
import { usePanier } from "../../hooks/usePanier";
import { useAuth } from "../../hooks/useAuth";

export default function BarreNavigation() {
  const { totalArticles } = usePanier();
  const { utilisateur, deconnecter } = useAuth();
  const location = useLocation();

  const initiales = utilisateur?.nom
    ? utilisateur.nom.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2)
    : "U";

  return (
    <>
      {/* 🔝 TOP BAR */}
      <header style={{
        height: "70px",
        background: "white",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 25px",
        borderBottom: "1px solid #f1f3f5",
        position: "fixed",
        top: 0,
        left: "220px",
        right: 0,
        zIndex: 100
      }}>

        {/* 🔍 Search */}
        <div style={{
          flex: 1,
          maxWidth: "480px",
          display: "flex",
          alignItems: "center",
          background: "#F1F3F5",
          borderRadius: "12px",
          padding: "10px 14px",
          gap: "10px"
        }}>
          <svg width="18" height="18" viewBox="0 0 24 24"
            fill="none" stroke="#868E96" strokeWidth="2">
            <circle cx="11" cy="11" r="8"/>
            <line x1="21" y1="21" x2="16.65" y2="16.65"/>
          </svg>

          <input
            type="text"
            placeholder="Rechercher un produit..."
            style={{
              border: "none",
              outline: "none",
              background: "transparent",
              width: "100%"
            }}
          />
        </div>

        {/* Actions */}
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>

          {/* 🔔 Notifications */}
          <div style={iconBox}>
            <svg width="18" height="18" viewBox="0 0 24 24"
              fill="none" stroke="#495057" strokeWidth="1.8">
              <path d="M18 8a6 6 0 10-12 0c0 7-3 7-3 7h18s-3 0-3-7"/>
              <path d="M13.73 21a2 2 0 01-3.46 0"/>
            </svg>
            <span style={badge}>2</span>
          </div>

          {/* 🛒 Panier */}
          <div style={iconBox}>
            <svg width="18" height="18" viewBox="0 0 24 24"
              fill="none" stroke="#495057" strokeWidth="1.8">
              <circle cx="9" cy="21" r="1"/>
              <circle cx="20" cy="21" r="1"/>
              <path d="M1 1h4l2.68 13.39a2 2 0 002 1.61h9.72a2 2 0 002-1.61L23 6H6"/>
            </svg>

            {totalArticles > 0 && (
              <span style={badge}>{totalArticles}</span>
            )}
          </div>

          {/* 👤 User */}
          <div style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            cursor: "pointer"
          }}>
            <div style={{
              width: "34px",
              height: "34px",
              borderRadius: "50%",
              background: "#3B5BDB",
              color: "white",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontWeight: 600
            }}>
              {initiales}
            </div>

            <span style={{
              fontSize: "13px",
              fontWeight: 600
            }}>
              {utilisateur ? utilisateur.nom.split(" ")[0] : "Invité"}
            </span>
          </div>

        </div>
      </header>

      {/* 📌 SIDEBAR (ta version) */}
      <aside style={{
        width: "220px",
        background: "white",
        borderRight: "0.5px solid #e9ecef",
        height: "100vh",
        position: "fixed",
        top: 0,
        left: 0,
        display: "flex",
        flexDirection: "column",
      }}>

        {/* Logo */}
        <div style={{ padding: "20px", borderBottom: "1px solid #eee" }}>
          <b style={{ color: "#3B5BDB" }}>E-Store</b>
        </div>

        {/* Menu */}
        <nav style={{ padding: "10px" }}>
          {[
            { path: "/", label: "Accueil" },
            { path: "/catalogue", label: "Catalogue" },
            { path: "/panier", label: "Panier" },
            { path: "/mes-commandes", label: "Mes commandes" },
            { path: "/profil", label: "Profil" },
          ].map(item => {
            const actif = location.pathname === item.path;

            return (
              <Link
                key={item.path}
                to={item.path}
                style={{
                  display: "block",
                  padding: "10px",
                  borderRadius: "8px",
                  marginBottom: "5px",
                  textDecoration: "none",
                  background: actif ? "#EEF2FF" : "transparent",
                  color: actif ? "#3B5BDB" : "#495057"
                }}
              >
                {item.label}
              </Link>
            );
          })}
        </nav>

        {/* Footer */}
        <div style={{ marginTop: "auto", padding: "10px" }}>
          {utilisateur ? (
            <button onClick={deconnecter}>Se déconnecter</button>
          ) : (
            <Link to="/connexion">Se connecter</Link>
          )}
        </div>
      </aside>
    </>
  );
}

/* styles */
const iconBox = {
  position: "relative",
  width: "36px",
  height: "36px",
  borderRadius: "10px",
  background: "#F8F9FA",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  cursor: "pointer"
};

const badge = {
  position: "absolute",
  top: "3px",
  right: "3px",
  background: "#FA5252",
  color: "white",
  fontSize: "10px",
  borderRadius: "50%",
  padding: "2px 5px"
};
